const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'workActivity.staleTasks error');
const tasks = JSON.parse(rpc.result?.content?.[0]?.text ?? '[]');
const N = 5; // matches the days:5 argument above
const items = [];
for (const t of (Array.isArray(tasks) ? tasks : [])) {
  if (t.assigneeUserId) {
    items.push({ taskId: t.taskId, title: t.title, projectId: t.projectId, projectName: t.projectName, daysStale: t.daysStale, recipientId: t.assigneeUserId, escalate: false });
  }
  // >=2N: ALSO notify the project owner (in addition to the assignee nag above, not instead of).
  if (t.daysStale >= 2 * N && t.projectOwnerUserId) {
    items.push({ taskId: t.taskId, title: t.title, projectId: t.projectId, projectName: t.projectName, daysStale: t.daysStale, recipientId: t.projectOwnerUserId, escalate: true });
  }
}
if (items.length === 0) return []; // nothing stale -> stop
return items.map((it) => ({ json: it }));

